def solve(n, edges, s, t):
    if s == t:
        return 0
    from collections import deque

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford algorithm to detect negative cycles and find shortest path
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n-1):
        updated = False
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    # Check for negative weight cycles that are reachable from s
    for u in range(n):
        if dist[u] == float('inf'):
            continue
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                # If there's a negative cycle that is reachable from s and can reach t, then it's unbounded
                if t in [x for x, _ in graph[u]] or t in [x for x, _ in graph[v]]:
                    return -1

    return dist[t] if dist[t] != float('inf') else -1

