    # Bellman-Ford algorithm to detect negative weights and find shortest path
    # Since weights are non-negative, Dijkstra's is more efficient, but Bellman-Ford is used here
    # to avoid using priority queues and for simplicity
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n-1):
        updated = False
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    if dist[t] == float('inf'):
        return -1
    return dist[t]
