def solve(n, edges, s, t):
    from collections import deque

    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bellman-Ford algorithm to handle negative weights and detect unreachable nodes
    dist = [float('inf')] * n
    dist[s] = 0

    for i in range(n - 1):
        updated = False
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    if dist[t] == float('inf'):
        return -1
    return dist[t]

