def solve(n, edges):
    parents = [i for i in range(n)]
    for i in range(n):
        if not isinstance(edges[i], list):
            edges[i] = list(edges[i])
        if len(edges[i]) == 1:
            edges[i].append(edges[i][0])
        if len(edges[i]) == 2:
            u, v = edges[i]
            if u > v:
                u, v = v, u
            if u != v:
                for j in range(u, v + 1):
                    if j <= v:
                        parents[j] = parents[u]
