def solve(n, edges):
    # We'll use Union-Find to find the number of connected components.
    # Since it's a graph, we can use Union-Find (Disjoint Set Union - DSU) to efficiently compute the number of connected components.

    parent = list(range(n))

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]  # Path compression
            u = parent[u]
        return u

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            parent[root_v] = root_u

    for u, v in edges:
        union(u, v)

    # Count the number of unique roots (connected components)
    components = set()
    for i in range(n):
        components.add(find(i))

    return len(components)

