    from collections import defaultdict

    # Build adjacency list
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    components = 0

    def dfs(node):
        stack = [node]
        visited[node] = True
        while stack:
            current = stack.pop()
            for neighbor in graph[current]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    stack.append(neighbor)

    for i in range(n):
        if not visited[i]:
            dfs(i)
            components += 1

    return components

