    # using a set to represent the graph
    # and a list to represent visited nodes
    visited = [False] * n
    count = 0

    for i in range(n):
        if not visited[i]:
            count += 1
            # Use BFS to mark all nodes in the component
            from collections import deque
            q = deque()
            q.append(i)
            visited[i] = True
            while q:
                node = q.popleft()
                for neighbor in get_neighbors(node, edges, n):
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        q.append(neighbor)

