def solve(n, edges):
    def dfs(u, v):
        if u == v:
            return
        if u not in parents and v not in parents:
            parents[u] = v
            parents[v] = u
            dfs(u, v)
    parents = {}
    for u, v in edges:
        parents[u] = v
        parents[v] = u
    components = 0
    visited = set()
    for i in range(n):
        if i not in visited:
            components += 1
            stack = [i]
            visited.add(i)
            while stack:
                node = stack.pop()
                for neighbor in [parents.get(node, None), parents.get(node, None)]:
                    if neighbor is not None and neighbor not in visited:
                        visited.add(neighbor)
                        stack.append(neighbor)
    return components

