    visited = set()
    for i in range(n):
        if i not in visited:
            components += 1
            stack = [i]
            visited.add(i)
            while stack:
                node = stack.pop()
                for neighbor in [parents.get(node, None), parents.get(node, None)]:
                    if neighbor is not None and neighbor not in visited:
                        visited.add(neighbor)
                        stack.append(neighbor)
    return components
