def solve(n, edges):
    from collections import defaultdict
    import sys
    import random

    # Create adjacency list
    graph = defaultdict(set)
    for u, v in edges:
        graph[u].add(v)
        graph[v].add(u)

    visited = set()

    def dfs(node):
        if node in visited:
            return
        visited.add(node)
        for neighbor in graph.get(node, []):
            dfs(neighbor)

    components = 0
    for node in range(n):
        if node not in visited:
            dfs(node)
            components += 1

    return components

