def solve(n, edges):
    # Create a set to track visited nodes
    visited = set()

    # Iterate through each edge
    for u, v in edges:
        if u not in visited:
            visited.add(u)
        if v not in visited:
            visited.add(v)

    # The number of connected components is the number of nodes not in the visited set
    return n - len(visited)

