from collections import deque

def solve(n, edges, s, t):
    if s == t:
        return 0
    dist = [float('inf')] * n
    dist[s] = 0
    prev = [-1] * n
    visited = [False] * n
    queue = deque([s])

    while queue:
        u = queue.popleft()
        visited[u] = True
        for v, w in get_adjacent_edges(u, edges):
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                prev[v] = u
                if not visited[v]:
                    queue.append(v)

    if dist[t] == float('inf'):
        return -1
    return dist[t]

def get_adjacent_edges(u, edges):
    adjacent = []
    for u_edge, v_edge, w_edge in edges:
        if u_edge == u:
            adjacent.append((v_edge, w_edge))
    return adjacent

