def solve(grid, start, goal):
    import heapq

    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    visited = set()
    heap = [(0, start[0], start[1])]
    parent = {}

    while heap:
        _, r, c = heapq.heappop(heap)
        if (r, c) == goal:
            path = []
            while (r, c) != start:
                path.append((r, c))
                r, c = parent[(r, c)]
            path.append(start)
            return path[::-1]

        if (r, c) in visited:
            continue

        visited.add((r, c))

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                parent[(nr, nc)] = (r, c)
                heapq.heappush(heap, (1, nr, nc))

    return []

