def solve(grid, start, goal):
    from collections import deque

    if not grid or start == goal:
        return [start] if grid[start[0]][start[1]] == '.' else []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Check if a cell is valid
    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # Avoid the man, house, and baby
    # For this example, assume 'M' is man, 'H' is house, 'B' is baby
    def is_forbidden(r, c):
        return grid[r][c] in ['M', 'H', 'B']

    # BFS with priority (A* search for shortest path)
    def a_star(start, goal):
        open_set = [(0, start)]
        came_from = {}
        g_score = {start: 0}
        f_score = {start: heuristic(start, goal)}

        while open_set:
            _, current = heapq.heappop(open_set)
            if current == goal:
                # Reconstruct path
                path = [current]
                while path[-1] != start:
                    path.append(came_from[path[-1]])
                    path.reverse()
                return path

            for dr, dc in directions:
                neighbor = (current[0] + dr, current[1] + dc)
                if not is_valid(*neighbor) or is_forbidden(*neighbor):
                    continue

                tentative_g_score = g_score[current] + 1
                if neighbor not in g_score or tentative_g_score < g_score[neighbor]:
                    came_from[neighbor] = current
                    g_score[neighbor] = tentative_g_score
                    f_score[neighbor] = tentative_g_score + heuristic(neighbor, goal)
                    heapq.heappush(open_set, (f_score[neighbor], neighbor))

        return None

    def heuristic(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    # Ensure start and goal are valid
    if not is_valid(*start) or not is_valid(*goal) or is_forbidden(*start) or is_forbidden(*goal):
        return []

    path = a_star(start, goal)
    if path:
        return path
    return []

