    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Check if start or goal is blocked or restricted
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # Use Dijkstra's algorithm for shortest path
    pq = [(0, start[0], start[1])]
    visited = set()
    parent = {}

    while pq:
        dist, r, c = heapq.heappop(pq)
        if (r, c) == goal:
            break
        if (r, c) in visited:
            continue
        visited.add((r, c))

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == '#':
                    continue
                if (nr, nc) not in visited:
                    heapq.heappush(pq, (dist + 1, nr, nc))
                    parent[(nr, nc)] = (r, c)

    # Reconstruct path
    path = []
    current = goal
    while current != start:
        path.append(current)
        current = parent.get(current, None)
        if current is None:
            return []
    path.append(start)
    path.reverse()

