import heapq

def solve(grid, start, goal):
    if not grid or start == goal:
        if is_free(grid, start):
            return [start]
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = set()
    heap = [(0, start[0], start[1])]
    path_map = {}

    while heap:
        _, r, c = heapq.heappop(heap)
        if (r, c) == goal:
            path = []
            while (r, c) != start:
                path.append((r, c))
                r, c = path_map[(r, c)]
            path.append(start)
            return path[::-1]

        if (r, c) in visited:
            continue
        visited.add((r, c))

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                heapq.heappush(heap, (1, nr, nc))
                path_map[(nr, nc)] = (r, c)

    return []

def is_free(grid, pos):
    r, c = pos
    return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

