    visited = {}

    while pq:
        dist, r, c = heapq.heappop(pq)
        if (r, c) == goal:
            # Reconstruct path
            path = []
            while (r, c) != start:
                path.append((r, c))
                r, c = visited[(r, c)]
            path.append(start)
            return path[::-1]
        if (r, c) in visited:
            continue
        visited[(r, c)] = (r - directions[0][0], c - directions[0][1]) if (r - directions[0][0], c - directions[0][1]) in visited else (r - directions[1][0], c - directions[1][1]) if (r - directions[1][0], c - directions[1][1]) in visited else (r - directions[2][0], c - directions[2][1]) if (r - directions[2][0], c - directions[2][1]) in visited else (r - directions[3][0], c - directions[3][1])
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                heapq.heappush(pq, (dist + 1, nr, nc))

    return []

