def solve(grid, start, goal):
    import heapq

    # Check if start and goal are valid and not walls
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and grid[start[0]][start[1]] == '.'):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0]) and grid[goal[0]][goal[1]] == '.'):
        return []

    # If start and goal are the same
    if start == goal:
        return [start]

    # Define directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Priority queue for A* search
    heap = [(0, start)]
    came_from = {}
    cost = {start: 0}

    while heap:
        _, current = heapq.heappop(heap)
        if current == goal:
            # Reconstruct path
            path = [current]
            while current in came_from:
                current = came_from[current]
                path.append(current)
            path.reverse()
            return path

        for dx, dy in directions:
            next_cell = (current[0] + dx, current[1] + dy)
            if 0 <= next_cell[0] < len(grid) and 0 <= next_cell[1] < len(grid[0]) and grid[next_cell[0]][next_cell[1]] == '.':
                new_cost = cost[current] + 1
                if next_cell not in cost or new_cost < cost[next_cell]:
                    cost[next_cell] = new_cost
                    came_from[next_cell] = current
                    heapq.heappush(heap, (new_cost, next_cell))

    # No path found
    return []

