import heapq

def solve(grid, start, goal):
    if not grid or not start or not goal:
        return []

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def get_neighbors(r, c):
        return [(r + dr, c + dc) for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)] if is_valid(r + dr, c + dc)]

    # Dijkstra's algorithm for shortest path
    heap = [(0, start[0], start[1])]
    visited = set()
    parent = {}

    while heap:
        dist, r, c = heapq.heappop(heap)
        if (r, c) == goal:
            break
        if (r, c) in visited:
            continue
        visited.add((r, c))
        for nr, nc in get_neighbors(r, c):
            if (nr, nc) not in visited:
                parent[(nr, nc)] = (r, c)
                heapq.heappush(heap, (dist + 1, nr, nc))

    # Reconstruct path
    path = []
    current = goal
    while current in parent:
        path.append(current)
        current = parent[current]
    path.append(start)
    path.reverse()

    # Check if path is valid and all cells are free
    for i in range(len(path) - 1):
        r1, c1 = path[i]
        r2, c2 = path[i+1]
        if abs(r1 - r2) + abs(c1 - c2) != 1 or grid[r1][c1] != '.' or grid[r2][c2] != '.':
            return []

    return path if all(grid[r][c] == '.' for r, c in path) else []

