import random

def solve(grid, start, goal):
    # Check if start or goal is out of bounds
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []

    # Check if start or goal is a wall
    if grid[start[0]][start[1]] == '#':
        return []
    if grid[goal[0]][goal[1]] == '#':
        return []

    # Directions: up, right, down, left
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    visited = set()
    path = []

    def dfs(r, c):
        if (r, c) == goal:
            return True
        visited.add((r, c))
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] == '.' and (nr, nc) not in visited:
                    path.append((nr, nc))
                    if dfs(nr, nc):
                        return True
                    path.pop()
        return False

    # Try a random start direction to avoid getting stuck
    random.shuffle(directions)
    for dr, dc in directions:
        nr, nc = start[0] + dr, start[1] + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == '.':
            path.append((nr, nc))
            if dfs(nr, nc):
                return [start] + path
            path.pop()

