    # Create a frequency dictionary to count occurrences of each number
    freq = {}
    for num in nums:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Sort the unique numbers
    sorted_nums = sorted(freq.keys())

    # Traverse the sorted numbers to find the k-th smallest
    count = 0
    for num in sorted_nums:
        count += freq[num]
        if count >= k:
            return num
    return None  # In case k exceeds the length of nums (should not happen per problem constraints)

