        count = 0
        for num in nums:
            if num <= x:
                count += 1
        return count

    left = min(nums)
    right = max(nums)

    while left < right:
        mid = (left + right) // 2
        if count_less_equal(mid) < k:
            left = mid + 1
        else:
            right = mid

    return left

