import heapq

def solve(nums, k):
    min_heap = []
    for i, num in enumerate(nums):
        heapq.heappush(min_heap, (num, i))

    count = {}
    result = None

    while k > 0:
        val, idx = heapq.heappop(min_heap)
        if val not in count:
            count[val] = 1
            result = val
            k -= 1
        else:
            count[val] += 1
            if count[val] == 1:
                k -= 1
                result = val
    return result

