def solve(nums, k):
    # Use a min-heap to keep track of the k smallest elements
    heap = nums[:k]
    heapq.heapify(heap)

    for num in nums[k:]:
        if num < heap[0]:
            heapq.heappop(heap)
            heapq.heappush(heap, num)

    return heap[0]

