    unique_values = []
    for num in nums:
        if num not in unique_values:
            unique_values.append(num)
    # Sort the unique values
    unique_values.sort()
    # Count occurrences of each value
    count_map = {}
    for num in nums:
        count_map[num] = count_map.get(num, 0) + 1
    # Find the k-th smallest value
    current_count = 0
    for val in unique_values:
        current_count += count_map[val]
        if current_count >= k:
            return val

