def solve(n, edges):
    # Initialize parent array for Union-Find
    parent = list(range(n))

    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])  # Path compression
        return parent[u]

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            parent[root_v] = root_u  # Union by attaching root_v to root_u

    # Perform union operations
    for u, v in edges:
        union(u, v)

    # Find the number of unique roots (connected components)
    root_set = set()
    for i in range(n):
        root_set.add(find(i))

    return len(root_set)

